def is_majority(arr, n, x):
    # Find the first occurrence of x
    left = 0
    right = n - 1
    first_occurrence = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first_occurrence = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first_occurrence == -1:
        return False

    # Check if the element at index (first_occurrence + n//2) is x
    # If it is, then x appears more than n/2 times
    if first_occurrence + n // 2 < n and arr[first_occurrence + n // 2] == x:
        return True
    else:
        return False
```

